"""Before/after review; original issue timestamps never drift with new recordings."""
from pathlib import Path
import json, argparse, functools, http.server
from review_furious_789_1025 import RangeHandler,chapter
R=Path(__file__).resolve().parents[1]
O=R/'docs/previews/stage78_review_1025'
PAGE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>Furious boss review · October 25</title>
<style>*{box-sizing:border-box}body{margin:0;background:#080d15;color:#e4edf5;font:15px system-ui}main{max-width:1560px;margin:auto;padding:24px}h1{font-size:25px;margin:0 0 8px}p{color:#a7b8cb;line-height:1.5}a{color:#85e9e3}button{font:inherit;border:1px solid #30445c;background:#172337;color:#e4edf5;padding:9px 13px;border-radius:5px;cursor:pointer}button.active{border-color:#85e9e3;color:#85e9e3}.bar{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:20px}video{width:100%;display:block;background:#000;max-height:77vh}aside{border:1px solid #253950;border-radius:6px;padding:16px;max-height:87vh;overflow:auto;background:#0f1928}h2{font-size:17px;margin:0 0 8px}.finding{padding:12px 0;border-bottom:1px solid #263449}.finding button{font-size:13px;padding:5px 8px}small{color:#9db0c7;line-height:1.45}.tag{color:#a4e6b3;font-size:12px}.open{color:#efc586}#meta{min-height:44px}#clock{font-variant-numeric:tabular-nums;padding:9px}.chapter{display:block;margin:7px 0;text-align:left;width:100%;font-size:13px}.evidence{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:22px}.evidence img{width:100%;display:block}.evidence figcaption{font-size:12px;color:#9db0c7}figure{margin:0}@media(max-width:1050px){.layout{grid-template-columns:1fr}aside{max-height:none}.evidence{grid-template-columns:repeat(2,1fr)}}</style>
<main><h1>Furious · Stage 7, Stage 8 &amp; Stage 9</h1><p>Timestamped review of the original fights, with revised Stage 7/8 footage and native visual evidence.<br>All finding timestamps refer to <b>Original recordings</b>. Full fights use Cole, native invulnerability and input aiming; health, phases and defeats remain native.</p>
<div class="bar" id="stages"></div><div class="bar"><button data-build="before" class="active">Original recordings</button><button data-build="after">Revised build</button><a href="../../FURIOUS_789_REVIEW_1025.md">Full timestamped report</a></div>
<div class="layout"><div><video controls preload="metadata" id="video"></video><div class="bar"><button id="back">−1 frame</button><button id="next">+1 frame</button><button data-rate=".25">¼×</button><button data-rate=".5">½×</button><button data-rate="1">1×</button><span id="clock"></span><a id="save" download>Save MP4</a></div><p id="meta"></p><small>Frame stepping uses the encoded 30 fps. Stage9 retains its intended hidden twin health and native fusion; the hit overlay now follows hull rotation and scale. No new Stage9 full-fight recording was needed for that rendering correction.</small>
<div class="evidence"><figure><a href="../../../_shots/stage78_review_1025/probe/gait-09.png"><img src="../../../_shots/stage78_review_1025/probe/gait-09.png" alt="Warden walking"></a><figcaption>32 authored walking poses, planted support pairs</figcaption></figure><figure><a href="../../../_shots/stage78_review_1025/probe/eye-fire.png"><img src="../../../_shots/stage78_review_1025/probe/eye-fire.png" alt="Eye beam"></a><figcaption>Animated flare covers the measured eye</figcaption></figure><figure><a href="../../../_shots/stage78_review_1025/probe/arm-shatter.png"><img src="../../../_shots/stage78_review_1025/probe/arm-shatter.png" alt="Broken arm"></a><figcaption>Actual arm pixels detach and shatter</figcaption></figure><figure><a href="../../../_shots/stage78_review_1025/probe/download-25.21.png"><img src="../../../_shots/stage78_review_1025/probe/download-25.21.png" alt="Digital download completed"></a><figcaption>Download completion and branching lightning</figcaption></figure></div></div>
<aside><h2 id="title"></h2><div id="findings"></div><h2 style="margin-top:22px">Native phase markers</h2><div id="chapters"></div></aside></div></main>
<script>const $=s=>document.querySelector(s),v=$('#video');let data,stage=7,build='before';const fmt=t=>Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');
function select(){const c=data.clips.find(c=>c.stage===stage&&c.build===build);document.querySelectorAll('[data-stage]').forEach(b=>b.classList.toggle('active',+b.dataset.stage===stage));document.querySelectorAll('[data-build]').forEach(b=>b.classList.toggle('active',b.dataset.build===build));$('#title').textContent='Stage '+stage+' · Findings';$('#findings').replaceChildren();
for(const n of data.issues.filter(n=>n.stage===stage)){const r=document.createElement('div');r.className='finding';const b=document.createElement('button');b.textContent=fmt(n.start)+' · '+n.priority+' · '+n.category;b.onclick=()=>{if(build!=='before'){build='before';select();v.addEventListener('loadedmetadata',()=>{v.currentTime=n.start;v.pause()},{once:true})}else{v.currentTime=n.start;v.pause()}};const p=document.createElement('p');p.textContent=n.finding;const s=document.createElement('small');s.textContent=n.status;r.append(b,p,s);$('#findings').append(r)}
$('#chapters').replaceChildren();if(!c){v.removeAttribute('src');v.load();$('#meta').textContent=stage===9?'Use the original full fight and the native render regression evidence.':'Revised capture is being verified.';return}v.src=c.video;$('#save').href=c.video;$('#meta').textContent=(build==='before'?'Original · ':'Revised · ')+c.name+' · '+fmt(c.duration)+' · '+(c.completed?'Native defeat completed':'Encounter capture')+' · '+(c.verified?'Audio, decode and errors verified':'Verification pending');let last='',at=-100;for(const q of c.chapters||[]){const label=q.label||[q.phase,q.form,q.mode].filter(x=>x!==null&&x!==undefined).join(' / ');if(label===last||q.seconds-at<2)continue;last=label;at=q.seconds;const b=document.createElement('button');b.className='chapter';b.textContent=fmt(q.seconds)+' · '+label;b.onclick=()=>{v.currentTime=Math.max(0,q.seconds-.4);v.pause()};$('#chapters').append(b)}}
fetch('review.json').then(r=>r.json()).then(d=>{data=d;for(const n of [7,8,9]){const b=document.createElement('button');b.dataset.stage=n;b.textContent='Stage '+n;b.onclick=()=>{stage=n;select()};$('#stages').append(b)}select()});document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{build=b.dataset.build;select()});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>v.playbackRate=+b.dataset.rate);$('#back').onclick=()=>{v.pause();v.currentTime=Math.max(0,v.currentTime-1/30)};$('#next').onclick=()=>{v.pause();v.currentTime+=1/30};v.ontimeupdate=v.onloadedmetadata=()=>$('#clock').textContent=fmt(v.currentTime)+' / '+fmt(v.duration||0);</script></html>'''

def build():
 O.mkdir(parents=True,exist_ok=True)
 original=json.loads((R/'_shots/furious_789_1025/recordings.json').read_text())['clips']
 clips=[]
 for c in original:
  clips.append(dict(c,build='before',video='../../../_shots/furious_789_1025/'+c['video'],verified=True))
 for s in (7,8):
  files=list((R/'_shots/stage78_review_1025/full').glob(f'stage{s}*/report.json'))
  if not files:continue
  f=max(files,key=lambda p:p.stat().st_mtime);q=json.loads(f.read_text());v=f.parent/f'stage{s}-furious.mp4'
  if not v.exists():continue
  verification=f.parent/'verification.json';verified=verification.exists()and all(json.loads(verification.read_text())['checks'].values())
  clips.append(dict(stage=s,name={7:'Toxic Portal Warden',8:'Dracodia'}[s],build='after',video='../../../'+v.relative_to(R).as_posix(),completed=q['completed'],duration=q['timeline'][-1]['seconds'],verified=verified,chapters=[chapter(s,n)for n in q['timeline']]))
 issues=json.loads((R/'_shots/furious_789_1025/findings.json').read_text())['issues']
 (O/'index.html').write_text(PAGE,encoding='utf8');(O/'review.json').write_text(json.dumps(dict(clips=clips,issues=issues),indent=2),encoding='utf8')
 print(json.dumps(dict(page=str(O/'index.html'),originals=len(original),revised=sum(c['build']=='after'for c in clips))),flush=True)
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--serve',action='store_true');args=ap.parse_args();build()
 if args.serve:
  server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(RangeHandler,directory=str(R)));port=server.server_address[1]
  url=f'http://127.0.0.1:{port}/docs/previews/stage78_review_1025/index.html';(R/'_shots/stage78_review_1025/server.json').write_text(json.dumps(dict(url=url,port=port)))
  print(url,flush=True);server.serve_forever()
